#include "mc_current_request.h"
#include "mc_math.h"
MC_MotorTorqueRequest_t MC_CurrentRequest_Update(const MC_TorqueModelConfig_t *cfg, float correction_nm, float accel_ff, float velocity, bool enable, MC_CurrentRequestDebug_t *dbg) { MC_MotorTorqueRequest_t out = {0}; if (!cfg || !enable) return out; float t_acc = cfg->inertia_kg_m2 * accel_ff; float t_fric = cfg->static_friction_nm * MC_Math_Sign(velocity) + cfg->viscous_friction_nm_per_rad_s * velocity; float t = correction_nm + t_acc + t_fric; float lim = cfg->torque_limit_nm; if (lim <= 0.0f && cfg->torque_constant_nm_per_a > 0.0f) lim = cfg->current_limit_a * cfg->torque_constant_nm_per_a; float tl = MC_Math_Clamp(t, -lim, lim); if (dbg) { dbg->torque_feedback_nm = correction_nm; dbg->torque_accel_ff_nm = t_acc; dbg->torque_friction_ff_nm = t_fric; dbg->torque_limited_nm = tl; dbg->limited = (tl != t); } out.torque_nm = tl; out.current_limit_a = cfg->current_limit_a; out.enable = true; return out; }
MC_FocCurrentCommand_t MC_CurrentRequest_ToFocCommand(const MC_TorqueModelConfig_t *cfg, const MC_MotorTorqueRequest_t *request) { MC_FocCurrentCommand_t cmd = {0}; if (!cfg || !request || !request->enable || cfg->torque_constant_nm_per_a <= 0.0f) return cmd; cmd.iq_a = MC_Math_Clamp(request->torque_nm / cfg->torque_constant_nm_per_a, -request->current_limit_a, request->current_limit_a); cmd.id_a = 0.0f; cmd.enable = true; return cmd; }
